-- 0156: construction arcs for علم غفر ذنب قبل — every Qurʾānic use counted (عَلِمَ 382) — model كشف; every example checked in the muṣḥaf, every lemma in AL, every count against its verses.
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alima:direct', 'علم', 'b84fdd2bade6516b85ce8cee81', NULL, 'عَلِمَ + مفعول', NULL, 1, 170, '["2:30","2:33","2:60","2:65","2:77","2:78","2:80","2:143","2:151","2:169","2:197","2:220","2:235","2:239","2:255","2:270","3:7","3:29","3:140","3:142","3:166","3:167","4:43","4:63","4:83","4:113","5:94","5:97","5:99","5:104","5:116","6:3","6:50","6:59","6:60","6:91","7:28","7:33","7:62","7:160","7:188","8:23","8:60","8:70","9:16","9:43","9:78","9:97","9:101","10:5","10:18","10:68","11:5","11:6","11:31","11:49","11:79","12:51","12:81","12:86","12:89","12:96","13:8","13:33","13:42","14:9","14:38","15:24","16:8","16:19","16:23","16:56","16:70","16:78","16:91","17:12","18:22","19:65","20:7","20:110","21:4","21:24","21:28","21:39","21:110","22:5","22:70","22:76","24:29","24:31","24:33","24:41","24:63","24:64","25:6","26:132","26:197","27:25","27:65","27:74","28:38","28:69","29:3","29:11","29:42","29:45","29:52","30:7","31:34","32:17","33:5","33:18","33:50","33:51","34:2","34:14","34:21","36:36","36:76","38:88","40:19","41:22","42:25","45:9","47:19","47:26","47:30","47:31","48:18","48:25","48:27","49:16","49:18","50:4","50:16","56:61","56:62","57:4","57:25","58:7","64:4","67:14","70:39","74:31","81:14","82:5","82:12","87:7","96:5"]', 'أثرٌ يتميّزُ به الشيء ← إدراكُ الشيءِ نفسِه ← معرفتُه بعينه', 'a mark that sets a thing apart → see the thing itself, and know it', 'One object, and the verb means ''know it / know who it is'' (the books: عَلِمَ = عَرَفَ here). The object may be a noun, a pronoun, or a relative مَا / مَنْ / الَّذِينَ — also when the مَا comes first (مَا لَا تَعْلَمُونَ). In 2:143 and 34:21 the مِنْ belongs to مِمَّنْ, not to the verb (as the government row says); only at 2:220 does the tafsīr hang مِنَ ٱلْمُصْلِحِ on the verb, read as ''tell apart''.', NULL, '[{"kind":"context","label":"after_a_test","refs":["2:143","2:220","3:140","3:142","3:166","3:167","5:94","9:16","9:43","29:3","29:11","34:21","47:31","57:25"],"note_en":"God''s ''knowing'' after a trial: the books read it as bringing the thing out and sorting the true from the false, not as learning (Abū Ḥayyān 29:3, Ibn ʿĀshūr 2:143)."}]', '["lex:maqayis_lugha:blk_mqy_4ad83feb9c2f842f","lex:raghib_mufradat:blk_mfr_b714a83893cf332d","lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","lex:ibn_manzur_lisan_arab:blk_lsn_38a25188ac9e1a5b","lex:zabidi_taj_arus:blk_taj_2acf4b861bca7328","lex:lane_lexicon:blk_lane_3ba7a1bd06647d11","tafsir:abu_hayyan:29:3","tafsir:ibn_ashur:2:143","tafsir:abu_hayyan:2:220","tafsir:ibn_ashur:2:220"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alima:anna', 'علم', 'b84fdd2bade6516b85ce8cee81', NULL, 'عَلِمَ + أنَّ / أنْ (جملة)', NULL, 1, 97, '["2:26","2:77","2:102","2:106","2:107","2:144","2:187","2:194","2:196","2:203","2:209","2:223","2:231","2:233","2:235","2:244","2:259","2:260","2:267","5:34","5:40","5:49","5:92","5:97","5:98","5:113","6:33","6:114","6:135","7:75","8:24","8:25","8:28","8:40","8:41","8:66","9:2","9:3","9:36","9:42","9:63","9:78","9:104","9:123","11:14","11:39","11:79","11:93","12:52","12:73","12:80","13:19","13:42","14:52","15:97","16:39","16:103","17:102","18:12","18:21","19:75","20:71","20:135","21:65","22:54","22:70","24:25","25:42","26:227","28:13","28:50","28:75","28:78","36:16","37:158","39:52","42:18","42:35","47:19","49:7","54:26","57:17","57:20","57:29","61:5","63:1","65:12","67:17","67:29","69:49","72:24","72:28","73:20"]', 'إدراكُ الشيء ← الحكمُ عليه بما هو له ← يقينٌ بخبرٍ تامّ', 'know a thing → know a fact about it, and hold it as sure', 'The verb takes a whole statement, not a thing: أَنَّ (or light أَنْ) fills the place of the two objects. Where a question word, a مَا of denial or a لام cuts the verb off from a plain object (taʿlīq), the sense is the same — knowing how things stand — so those are kept here as a branch.', NULL, '[{"kind":"form","label":"imperative_bear_in_mind","refs":["2:194","2:196","2:203","2:209","2:223","2:231","2:233","2:235","2:244","2:260","2:267","5:34","5:49","5:92","5:98","8:24","8:25","8:28","8:40","8:41","9:2","9:3","9:36","9:123","11:14","28:50","47:19","49:7","57:17","57:20"],"note_en":"اِعْلَمُوا أَنَّ — not ''find out'' but ''keep this fact firmly before you'' (Ibn ʿĀshūr 47:19)."},{"kind":"form","label":"suspended_by_question_or_denial","refs":["2:102","6:33","6:135","9:42","11:39","11:79","11:93","12:73","13:42","17:102","18:12","19:75","20:71","20:135","21:65","25:42","26:227","36:16","37:158","42:35","54:26","63:1","67:17","67:29","72:24"],"note_en":"a question word (مَنْ، أَيّ، كَيْفَ), a مَا of denial, or إنَّ … لَـ stands where أنَّ would; in the threats (فَسَوْفَ تَعْلَمُونَ مَنْ …) the answer is left for events to give."}]', '["lex:raghib_mufradat:blk_mfr_d9460f9dbb9b8252","lex:zabidi_taj_arus:blk_taj_2acf4b861bca7328","lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","tafsir:ibn_ashur:47:19"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alima:two_obj', 'علم', 'b84fdd2bade6516b85ce8cee81', NULL, 'عَلِمَ + مفعولَين', NULL, 1, 1, '["60:10"]', 'الحكمُ على الشيء بصفةٍ ← بالأمارات بعد الامتحان ← ظنٌّ غالبٌ يُسمّى علمًا', 'know a thing → judge it to be so, from the signs', 'The only place where عَلِمَ takes a person and a description as two objects. Rāghib (and the Tāj after him) pair it with 8:60 to show the two kinds of عِلْم. The tafsīr says the ''knowing'' here is a strong judgement from oaths and signs, since only God knows the heart (ٱللَّهُ أَعْلَمُ بِإِيمَٰنِهِنَّ).', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_d9460f9dbb9b8252","lex:zabidi_taj_arus:blk_taj_2acf4b861bca7328","lex:ibn_manzur_lisan_arab:blk_lsn_38a25188ac9e1a5b","lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","tafsir:abu_hayyan:60:10","tafsir:razi:60:10","tafsir:alusi:60:10"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alima:bi', 'علم', 'b84fdd2bade6516b85ce8cee81', NULL, 'عَلِمَ (بـ) + أنَّ', 'بـ', 1, 1, '["96:14"]', 'العلمُ ← يُضمَّنُ معنى الشعور والإحاطة ← تدخلُ الباء', 'know → have it reach you, and take it in', 'Only here does the verb عَلِمَ itself take بِـ. The tafsīr is silent on this بِـ; the lexicons say بِـ comes in when عَلِمَ carries the sense of شَعَرَ ''become aware'' (Miṣbāḥ, Tāj), or of taking it all in, الإحاطة (Tāj) — the same gloss the government row gives عَلِيمٌ بِـ.', NULL, NULL, '["lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","lex:zabidi_taj_arus:blk_taj_839e6e388b615155","lex:zabidi_taj_arus:blk_taj_523cdf4c631affa0","lex:lane_lexicon:blk_lane_3ba7a1bd06647d11","tafsir:alusi:49:16"]', 0.75, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alima:absolute', 'علم', 'b84fdd2bade6516b85ce8cee81', NULL, 'عَلِمَ بلا مفعول', NULL, 0, 113, '["2:13","2:22","2:42","2:75","2:101","2:102","2:103","2:113","2:118","2:146","2:184","2:188","2:216","2:230","2:232","2:280","3:66","3:71","3:75","3:78","3:135","6:37","6:67","6:81","6:97","6:105","7:32","7:38","7:123","7:131","7:182","7:187","8:27","8:34","9:6","9:11","9:41","9:93","10:5","10:55","10:89","12:21","12:40","12:46","12:68","15:3","15:96","16:38","16:41","16:43","16:55","16:74","16:75","16:95","16:101","21:7","23:84","23:88","23:114","24:19","26:49","27:52","27:61","28:13","28:57","29:16","29:41","29:64","29:66","30:6","30:30","30:34","30:56","30:59","31:25","34:28","34:36","36:26","37:170","39:9","39:26","39:29","39:39","39:49","40:57","40:70","41:3","43:86","43:89","44:39","45:18","45:26","52:47","56:76","58:14","61:11","62:9","63:8","68:33","68:44","71:4","78:4","78:5","100:9","102:3","102:4","102:5"]', 'العلمُ ← يُنزَّلُ الفعلُ منزلةَ اللازم ← العالِمُ في مقابل الجاهل', 'know → be one who knows, with nothing named', 'No object at all, and none fronted: لَا يَعْلَمُونَ, إِن كُنتُمْ تَعْلَمُونَ, وَأَنتُمْ تَعْلَمُونَ. Ibn ʿĀshūr (39:9): the verb is treated as intransitive — ''those who have knowledge''. When مَا لَا تَعْلَمُونَ has a relative مَا, that مَا is the object, and the use belongs to the direct arc.', NULL, '[{"kind":"form","label":"threat_soon_you_will_know","refs":["6:67","7:123","15:3","15:96","16:55","26:49","29:66","30:34","37:170","39:39","40:70","43:89","78:4","78:5","102:3","102:4"],"note_en":"سَوْفَ تَعْلَمُونَ with nothing after it: what they will know is left unsaid, and that silence is the warning (Abū Ḥayyān 102:3, citing Zamakhsharī)."}]', '["tafsir:ibn_ashur:39:9","tafsir:abu_hayyan:102:3"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alim:bi', 'علم', '9ba7ce572be40ce777e0d44853', NULL, 'عَلِيم (بـ)', 'بـ', 1, 54, '["2:29","2:95","2:215","2:231","2:246","2:273","2:282","2:283","3:63","3:92","3:115","3:119","3:154","4:32","4:39","4:127","4:176","5:7","5:97","6:101","8:43","8:75","9:44","9:47","9:115","10:36","11:5","12:19","12:50","16:28","23:51","24:28","24:35","24:41","24:64","29:62","31:23","33:40","33:54","35:8","35:38","36:79","39:7","42:12","42:24","48:26","49:16","57:3","57:6","58:7","62:7","64:4","64:11","67:13"]', 'العلمُ ← يُراعى فيه معنى الإحاطة ← عليمٌ بالشيء: محيطٌ به', 'knowing → knowing that goes all round a thing', 'The بِـ phrase may come after (عَلِيمٌ بِذَاتِ ٱلصُّدُورِ) or before (بِكُلِّ شَيْءٍ عَلِيمٌ); fronting is word order, not a new government. Not here: 7:112, 10:79, 26:37 بِكُلِّ سَاحِرٍ عَلِيمٍ and 15:53, 51:28 بِغُلَٰمٍ عَلِيمٍ — that بِـ belongs to the verb before it; 4:70 وَكَفَىٰ بِٱللَّهِ عَلِيمًا — the بِـ belongs to كَفَىٰ.', NULL, '[{"kind":"word_order","label":"object_fronted","refs":["2:29","2:215","2:231","2:273","2:282","2:283","3:92","4:32","4:39","4:127","4:176","5:97","6:101","8:75","9:115","12:50","23:51","24:28","24:35","24:64","29:62","33:40","33:54","36:79","42:12","48:26","49:16","57:3","58:7","64:11"],"note_en":"بِكُلِّ شَيْءٍ عَلِيمٌ and the like — fronting is emphasis, not government"},{"kind":"object_semantics","label":"hearts","refs":["3:119","3:154","5:7","8:43","11:5","31:23","35:38","39:7","42:24","57:6","64:4","67:13"]},{"kind":"object_semantics","label":"people","refs":["2:95","2:246","3:63","3:115","4:39","9:44","9:47","62:7"],"note_en":"knowing the wrongdoers / the God-fearing: a warning or a promise that they will be dealt with"}]', '["lex:zabidi_taj_arus:blk_taj_523cdf4c631affa0","lex:lane_lexicon:blk_lane_3ba7a1bd06647d11","lex:ibn_manzur_lisan_arab:blk_lsn_3d2a9b7d2053951a"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:alim:bare', 'علم', '9ba7ce572be40ce777e0d44853', NULL, 'عَلِيم بلا متعلَّق', NULL, 0, 107, '["2:32","2:115","2:127","2:137","2:158","2:181","2:224","2:227","2:244","2:247","2:256","2:261","2:268","3:34","3:35","3:73","3:121","4:11","4:12","4:17","4:24","4:26","4:35","4:70","4:92","4:104","4:111","4:147","4:148","4:170","5:54","5:76","6:13","6:83","6:96","6:115","6:128","6:139","7:109","7:112","7:200","8:17","8:42","8:53","8:61","8:71","9:15","9:28","9:60","9:97","9:98","9:103","9:106","9:110","10:65","10:79","12:6","12:34","12:55","12:76","12:83","12:100","15:25","15:53","15:86","16:70","21:4","22:52","22:59","24:18","24:21","24:32","24:58","24:59","24:60","26:34","26:37","26:220","27:6","27:78","29:5","29:60","30:54","31:34","33:1","33:51","34:26","35:44","36:38","36:81","40:2","41:12","41:36","42:50","43:9","43:84","44:6","48:4","49:1","49:8","49:13","51:28","51:30","60:10","66:2","66:3","76:30"]', 'العلمُ ← مبالغةٌ فيه ← وصفٌ ثابتٌ لا يُقيَّدُ بمعلوم', 'knowing → knowing as what one is, with no object set', 'Most often paired with another name (سَمِيعٌ عَلِيمٌ, عَلِيمٌ حَكِيمٌ, وَاسِعٌ عَلِيمٌ). Al-Rāzī (2:32): the full force of عَلِيم means taking in all that can be known, which is God''s alone. Said of a person, it is measured and limited: a skilled sorcerer, Yūsuf over the stores, the boy promised to Ibrāhīm, and 12:76 ''over every knower is one who knows more'' (Rāghib). The plural عُلَمَاء at 26:197 and 35:28 is filed under this lemma but is a noun, ''people of knowledge'', and is left out.', NULL, '[{"kind":"subject","label":"said_of_a_person","refs":["7:109","7:112","10:79","12:55","12:76","15:53","26:34","26:37","51:28"],"note_en":"a person''s knowing is always bounded by what the context names"}]', '["tafsir:razi:2:32","tafsir:ibn_ashur:2:32","lex:raghib_mufradat:blk_mfr_f50f49d0798b2624"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:allama:two_obj', 'علم', '2b5ea997b195cb4b96e6e4c221', NULL, 'عَلَّمَ + مفعولَين', NULL, 1, 31, '["2:31","2:32","2:102","2:129","2:151","2:239","2:251","3:48","3:164","4:113","5:4","5:110","6:91","12:6","12:21","12:37","12:68","12:101","18:65","18:66","20:71","21:80","26:49","27:16","36:69","55:4","62:2","96:5"]', 'جعلُه عالِمًا ← إلقاءُ الشيء في نفسه شيئًا بعد شيء ← تعليمُ أحدٍ شيئًا', 'make someone know → put the thing into him, bit by bit', 'Both sides named: the learner, then the lesson. The lesson may be a relative مَا (مَا لَمْ تَعْلَمُوا). Rāghib (in the Tāj): تَعْلِيم is teaching by repetition until it settles, unlike إِعْلَام, a quick telling.', NULL, '[{"kind":"harf","label":"min_some_of","refs":["2:251","5:4","12:6","12:21","12:101","18:66"],"note_en":"مِنْ in place of the second object: he was taught a part of it — of the meaning of dreams, of what God wills"},{"kind":"voice","label":"passive","refs":["6:91","18:66","27:16"],"note_en":"the learner becomes subject; the lesson stays as object"}]', '["lex:lane_lexicon:blk_lane_c3d4a7f0a1c1e2d4","lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","lex:ibn_manzur_lisan_arab:blk_lsn_fbff29b363a2e069","lex:zabidi_taj_arus:blk_taj_e31f359f5acdf15f","lex:raghib_mufradat:blk_mfr_3b6f764ab52ecae5"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:allama:one_side', 'علم', '2b5ea997b195cb4b96e6e4c221', NULL, 'عَلَّمَ + مفعولٌ واحد / بلا مفعول', NULL, 1, 9, '["2:102","2:282","3:79","5:4","16:103","53:5","55:2","96:4"]', 'التعليمُ ← يُحذَفُ المتعلِّمُ أو العِلمُ ← يُقصَدُ إلى الطرف المذكور', 'teach → with the learner or the lesson left out, so the stress falls on what is left', 'Not a different meaning of ''teach'' — a different stress. At 55:2 the learner is dropped, so the gift is the teaching itself, not who got it (Abū Ḥayyān). At 96:4 both sides are dropped and only the means remains: the pen. 3:79 counts here (تُعَلِّمُونَ ٱلْكِتَٰبَ, no learner).', NULL, '[{"kind":"omission","label":"learner_unsaid","refs":["3:79","55:2"]},{"kind":"omission","label":"lesson_unsaid","refs":["2:102","2:282","5:4","16:103","53:5"]},{"kind":"omission","label":"both_unsaid","refs":["96:4"]}]', '["tafsir:abu_hayyan:55:2","tafsir:alusi:96:4","lex:raghib_mufradat:blk_mfr_efd4bfffa2cd8244"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:علم:allama:bi', 'علم', '2b5ea997b195cb4b96e6e4c221', NULL, 'عَلَّمَ + مفعول + (بـ)', 'بـ', 1, 1, '["49:16"]', 'التعليمُ ← من «علمتُ به» ← إخبارُ أحدٍ بأمرٍ', 'teach → tell someone of a thing', 'The only عَلَّمَ with بِـ. Ālūsī: it comes from عَلِمْتُ بِهِ, so the doubled form takes the person directly and the matter by بِـ — ''inform''. The Miṣbāḥ gives the same pattern for أَعْلَمْتُهُ بِهِ. Said to people who would ''inform'' God of their faith, it mocks them.', NULL, NULL, '["tafsir:alusi:49:16","lex:fayyumi_misbah_munir:blk_msb_9442c830ac3bbd3b","lex:zabidi_taj_arus:blk_taj_e31f359f5acdf15f"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:ghafara:direct', 'غفر', '3f3548d833da9f61454be329f9', NULL, 'غَفَرَ + مفعول', NULL, 1, 4, '["3:135","4:48","4:116","39:53"]', 'سَتْرُ الشيء ← سَتْرُ الذنبِ نفسِه ← فلا يُرى', 'cover a thing → cover the sin itself, so it is no longer seen', 'The verb reaches only the sin; no person is named. Always God. At 4:48 and 4:116 the first يَغْفِرُ takes أَن يُشْرَكَ بِهِ as object (this arc); the second adds لِمَن يَشَآءُ and belongs to the لـ arc.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_5e92a21d8d683be2","lex:lane_lexicon:blk_lane_53f5f09ead6a2304","lex:ibn_manzur_lisan_arab:blk_lsn_c9c376c34531810d","lex:raghib_mufradat:blk_mfr_875c2509db26c773"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:ghafara:li', 'غفر', '3f3548d833da9f61454be329f9', NULL, 'غَفَرَ (لـ) ± مفعول', 'لـ', 0, 57, '["2:58","2:284","2:286","3:16","3:31","3:129","3:147","3:193","4:48","4:116","4:137","4:168","5:18","5:40","5:118","7:23","7:149","7:151","7:155","7:161","7:169","8:29","8:38","8:70","9:80","11:47","12:92","14:10","14:41","20:73","23:109","24:22","26:51","26:82","26:86","28:16","33:71","36:27","38:25","38:35","40:7","45:14","46:31","47:34","48:2","48:14","57:28","59:10","60:5","61:12","63:6","64:17","66:8","71:4","71:7","71:28"]', 'سَتْرُ الذنب ← لأجلِ صاحبِه ← فلا يُؤاخَذُ به', 'cover the sin → for someone, so it is not held against him', 'لـ names the person who gains (the government row: lām of ''for''). The sin may be named after it (لَنَا ذُنُوبَنَا) or left out (لِمَن يَشَآءُ) — the sense is the same, so it is one arc with a branch. With مِنْ ذُنُوبِكُمْ (14:10, 46:31, 71:4) Zamakhsharī notes this form is said to unbelievers, plain ذُنُوبَكُمْ to believers.', NULL, '[{"kind":"object","label":"sin_named","refs":["2:58","3:16","3:31","3:147","3:193","4:48","4:116","7:161","8:38","20:73","26:51","26:82","33:71","38:25","48:2","61:12"]},{"kind":"harf","label":"min_some_of","refs":["14:10","46:31","71:4"],"note_en":"مِنْ ذُنُوبِكُمْ — ''some of your sins''; Abū ʿUbayda and al-Akhfash took مِنْ as extra (Abū Ḥayyān 14:10)"},{"kind":"subject","label":"people_forgiving_people","refs":["45:14"],"note_en":"said of people: let it pass outwardly (Rāghib on 45:14)"}]', '["lex:lane_lexicon:blk_lane_8d21a7cc45be169d","lex:fayyumi_misbah_munir:blk_msb_7833c08efd546919","lex:jawhari_sihah:blk_sih_1bc77a4aec5a1e93","lex:raghib_mufradat:blk_mfr_640b1dae79c8a58e","lex:raghib_mufradat:blk_mfr_8ee6965b2cb13143","tafsir:zamakhshari:14:10"]', 0.95, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:ghafara:absolute', 'غفر', '3f3548d833da9f61454be329f9', NULL, 'غَفَرَ بلا متعلَّق', NULL, 0, 4, '["23:118","42:37","42:43","64:14"]', 'السَّتْرُ ← لا يُذكَرُ مستورٌ ولا مَستورٌ له ← الصفحُ خُلُقًا', 'cover → be one who covers wrongs, with no one named', 'Nothing follows the verb. Three of the four are people letting a wrong pass (42:37, 42:43, 64:14); Zamakhsharī (in Abū Ḥayyān 42:37) reads هُمْ يَغْفِرُونَ as ''they are the ones marked by forgiving, even in anger''. 23:118 رَبِّ ٱغْفِرْ وَٱرْحَمْ is a prayer to God with both objects left open.', NULL, '[{"kind":"subject","label":"people_forgiving_people","refs":["42:37","42:43","64:14"]}]', '["lex:raghib_mufradat:blk_mfr_8ee6965b2cb13143","tafsir:abu_hayyan:42:37"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:istaghfara:direct', 'غفر', '25404d93e809778d1c2bbcef5e', NULL, 'اسْتَغْفَرَ + مفعول (الله)', NULL, 1, 16, '["2:199","4:64","4:106","4:110","5:74","11:3","11:52","11:61","11:90","18:55","27:46","38:24","41:6","71:10","73:20","110:3"]', 'طلبُ السَّتر ← من الله ← بالقول والفعل', 'ask for covering → ask it of God, in word and in deed', 'The object is the one asked — always God (رَبَّكُمْ, ٱللَّهَ, or a pronoun for Him). Rāghib on 71:10: they were told to ask by tongue and by deed. The sin is never the object here in the Qurʾān, though the books allow اسْتَغْفَرَ ٱللَّهَ ذَنْبَهُ.', NULL, NULL, '["lex:fayyumi_misbah_munir:blk_msb_7833c08efd546919","lex:lane_lexicon:blk_lane_dbb411a6cfe65dd2","lex:raghib_mufradat:blk_mfr_6e5128ad5f5d3cf3","lex:ibn_manzur_lisan_arab:blk_lsn_c0b02d487dcc7d5d"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:istaghfara:li_dhanb', 'غفر', '25404d93e809778d1c2bbcef5e', NULL, 'اسْتَغْفَرَ (لـ) + ذنب', 'لـ', 0, 4, '["3:135","12:29","40:55","47:19"]', 'طلبُ السَّتر ← لذنبٍ مُعيَّن ← اعترافٌ به', 'ask for covering → for a fault of your own, named', 'لـ here points to the sin itself. The Ṣiḥāḥ and Lisān: اسْتَغْفَرَ لِذَنْبِهِ and مِنْ ذَنْبِهِ mean the same. Ibn ʿĀshūr (47:19): the لـ of لِذَنۢبِكَ is ''lām of specifying'' standing for a second object; the لـ of وَلِلْمُؤْمِنِينَ that follows is a different one — see the next arc.', NULL, NULL, '["lex:lane_lexicon:blk_lane_dbb411a6cfe65dd2","lex:jawhari_sihah:blk_sih_1bc77a4aec5a1e93","lex:ibn_manzur_lisan_arab:blk_lsn_797b2023ed278fdf","tafsir:ibn_ashur:47:19"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:istaghfara:li_person', 'غفر', '25404d93e809778d1c2bbcef5e', NULL, 'اسْتَغْفَرَ (لـ) + شخص', 'لـ', 0, 19, '["3:159","4:64","9:80","9:113","12:97","12:98","19:47","24:62","40:7","42:5","47:19","48:11","60:4","60:12","63:5","63:6"]', 'طلبُ السَّتر ← لغيرِك ← شفاعةٌ له', 'ask for covering → for someone else: plead on his behalf', 'لـ names the person prayed for, never the one praying. 47:19 holds both kinds in one verb: لِذَنۢبِكَ (own fault) and وَلِلْمُؤْمِنِينَ (others: Ibn ʿĀshūr — lām of ''for the sake of'', their sins understood); it is counted in both arcs.', NULL, '[{"kind":"object","label":"god_also_named","refs":["12:98","19:47","24:62","60:12"],"note_en":"سَأَسْتَغْفِرُ لَكَ رَبِّي — the person by لـ and God as object together"},{"kind":"object","label":"sin_also_named","refs":["12:97"],"note_en":"اسْتَغْفِرْ لَنَا ذُنُوبَنَا — the sins as object, the people by لـ"}]', '["lex:raghib_mufradat:blk_mfr_75878a5ada007f51","lex:raghib_mufradat:blk_mfr_b5fee78d7e654959","tafsir:ibn_ashur:47:19","tafsir:ibn_ashur:9:80"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:istaghfara:absolute', 'غفر', '25404d93e809778d1c2bbcef5e', NULL, 'اسْتَغْفَرَ بلا متعلَّق', NULL, 0, 2, '["8:33","51:18"]', 'طلبُ السَّتر ← لا يُذكَرُ مسؤولٌ ولا ذنب ← عادةٌ قائمة', 'ask for covering → as a standing habit, nothing named', 'No object and no لـ: the asking is described as something they keep doing. Ibn ʿĀshūr (8:33): what counts is turning from shirk, not words alone.', NULL, NULL, '["tafsir:abu_hayyan:51:18","tafsir:ibn_ashur:8:33"]', 0.8, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:غفر:ghafir:idafa', 'غفر', 'ea923679f32861b46d50eade95', NULL, 'غافِر مضافًا', NULL, 1, 1, '["40:3"]', 'الساتر ← يُسمّى بما يستره ← صفةٌ ثابتةٌ لا حدثٌ في زمن', 'the one who covers → named by what he covers, as a lasting mark', 'The participle is joined to its object (غَافِرِ ٱلذَّنۢبِ) instead of taking it by a verb. Ālūsī: these participles are not about one act at one time but a fixed, lasting trait — which is why the iḍāfa makes them true epithets of God (Ibn ʿĀshūr: definite epithets). The only other غَافِر, 7:155 خَيْرُ ٱلْغَٰفِرِينَ, is plural with nothing covered named, and stands outside this arc.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_a582812d56c0533a","lex:raghib_mufradat:blk_mfr_019d45eb38b04893","tafsir:alusi:40:3","tafsir:ibn_ashur:40:3"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:ذنب:dhanb:bi', 'ذنب', '2e7a23ca384799c20b92778cf7', NULL, 'بِـ + ذَنْب (سببيّة)', 'بـ', 0, 11, '["3:11","5:18","5:49","6:6","7:100","8:52","8:54","29:40","40:21","81:9","91:14"]', 'ذَنَبُ الشيء: مؤخَّرُه ← ما يتبعُ الفعلَ من عاقبة ← يُؤخَذُ به صاحبُه', 'the tail of an act → what follows behind it, and brings the seizing', 'بِـ of cause after a verb of seizing, ruining or striking. Rāghib: the sin is called ذَنْب from the tail (ذَنَب), because its outcome trails behind it, and cites فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمْ. Not here: اعْتَرَفُوا بِذُنُوبِهِمْ (9:102, 40:11, 67:11) and خَبِيرًا بِذُنُوبِ (17:17, 25:58) — there the بِـ belongs to the verb or adjective.', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_4b5f55594d6ec275","lex:raghib_mufradat:blk_mfr_4913f32df599d194","lex:khalil_kitab_ayn:blk_kay_027e544a5013b5bf","tafsir:abu_hayyan:3:11","tafsir:zamakhshari:91:14"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:ذنب:dhanb:lahum_ala', 'ذنب', '2e7a23ca384799c20b92778cf7', NULL, 'ذَنْبٌ (لـ … عَلَى)', 'لـ / على', 0, 1, '["26:14"]', 'الجُرم ← تَبِعتُه ← حقٌّ يُطالَبُ به لهم عليك', 'a wrong done → turned into a claim others hold against you', 'Only at 26:14. لـ names those who hold the claim, عَلَى the one it lies on. The tafsīr: the ''sin'' here is its consequence — the right to demand blood for the slain Copt (Ibn ʿĀshūr); a sin ''in their eyes'' (Ālūsī).', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_c31c39ad6009585e","lex:raghib_mufradat:blk_mfr_4913f32df599d194","tafsir:alusi:26:14","tafsir:ibn_ashur:26:14","tafsir:abu_hayyan:26:14"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:qabila:min', 'قبل', '3976fb0950c0e47f9ba8096bb0', NULL, 'قَبِلَ + مفعول + (مِن)', 'مِن', 1, 5, '["2:48","2:123","3:85","3:91","9:54"]', 'مواجهةُ الشيء ← أخذُ ما يُقدَّمُ ← من يدِ صاحبه', 'face what is held out → take it from the one who offers it', 'مِنْ names the giver. All five are denied and passive — ransom, intercession, spending, a religion other than Islam: ''it will not be taken from him''. At 3:85 the object is understood (the religion he sought).', NULL, NULL, '["lex:maqayis_lugha:blk_mqy_74b390e5edcd67a8","lex:lane_lexicon:blk_lane_5f490dd1ca203137","lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001","lex:raghib_mufradat:blk_mfr_a98aa671ca3e65a5","lex:zabidi_taj_arus:blk_taj_0cb61b98e8d8669c"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:qabila:an', 'قبل', '3976fb0950c0e47f9ba8096bb0', NULL, 'قَبِلَ + مفعول + (عَن)', 'عَن', 1, 2, '["9:104","42:25"]', 'أخذُ التوبة ← متجاوزًا عن الذنب ← فينفصلُ عنهم', 'take the repentance → and let the sin pass off them', 'Both with التَّوْبَة as object and God as subject. The Lisān treats مِنْ and عَنْ alike here (as the government row notes); the tafsīr gives عَنْ its own weight: Ālūsī — the verb carries ''passing over and pardoning''; Abū Ḥayyān — عَنْ is ''moving away'', stronger than مِنْ.', NULL, NULL, '["lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001","lex:raghib_mufradat:blk_mfr_ecdb287599252f9b","lex:raghib_mufradat:blk_mfr_14d4d97dfb30f3d1","tafsir:alusi:9:104","tafsir:abu_hayyan:9:104"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:qabila:direct', 'قبل', '3976fb0950c0e47f9ba8096bb0', NULL, 'قَبِلَ + مفعول (بلا حرف)', NULL, 1, 2, '["3:90","24:4"]', 'أخذُ ما يُقدَّمُ ← الرضا به ← عَدُّه مقبولًا معتبَرًا', 'take what is offered → and count it as valid', 'No مِنْ or عَنْ: the owner is named inside the object phrase (تَوْبَتُهُمْ), or by لَهُمْ next to the noun, which Ālūsī reads as ''their testimony''. The verb says only whether the thing counts — both are denials.', NULL, NULL, '["lex:lane_lexicon:blk_lane_5f490dd1ca203137","lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001","tafsir:alusi:24:4"]', 0.75, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:qabil:idafa', 'قبل', '89060f9f3668b069e4ca2ada7a', NULL, 'قابِل مضافًا', NULL, 1, 1, '["40:3"]', 'القابلُ: من يتلقّى الدَّلوَ ← يتلقّى رجوعَ العبد ← صفةٌ ثابتة', 'the one who receives → named by what he receives: people turning back', 'Once, beside غَافِرِ ٱلذَّنۢبِ. التَّوْب is a masdar ''turning back'' (Ibn ʿĀshūr) or a collective of تَوْبَة (al-Rāzī). The و between the two names gives the repenter both mercies together: his turning is taken, and his sin is covered (Zamakhsharī, in Ālūsī and Ibn ʿĀshūr).', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_ecdb287599252f9b","lex:raghib_mufradat:blk_mfr_8252507abbd4dba3","tafsir:ibn_ashur:40:3","tafsir:razi:40:3","tafsir:alusi:40:3"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:taqabbala:min', 'قبل', 'b90cdc7da61367f79aaf032718', NULL, 'تَقَبَّلَ (مِن)', 'مِن', 0, 7, '["2:127","3:35","5:27","5:36","9:53"]', 'القبولُ ← على وجهٍ يقتضي ثوابًا ← من هذا المُقدِّم بعينه', 'take up what is offered → from this giver, so the giver is what is weighed', 'The offering is never named after the verb — only the giver, by مِنْ. Rāghib: تَقَبُّل is acceptance that brings reward, and ''not every act of worship is accepted'' (5:27).', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_8b94d2d6edc8f942","lex:raghib_mufradat:blk_mfr_df144a7c47479038","lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001","lex:zabidi_taj_arus:blk_taj_0cb61b98e8d8669c"]', 0.9, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:taqabbala:direct', 'قبل', 'b90cdc7da61367f79aaf032718', NULL, 'تَقَبَّلَ + مفعول', NULL, 1, 2, '["3:37","14:40"]', 'القبولُ ← للشيء المُقدَّم نفسِه ← رضًا به وتكفُّلٌ', 'take up the offering itself → receive it, and take it into care', 'Now the thing offered is the object and no giver is named. At 3:37 the ''offering'' is Maryam herself: Rāghib — ''He accepted her'', or ''He took charge of her''.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_548782de70b4e0d3","lex:raghib_mufradat:blk_mfr_17afd131c14fb569","lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001"]', 0.85, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc (id, root_norm, lemma_id, also_lemma_id, construction_ar, harf, has_object, attest_count, all_refs_json, arc_ar, arc_en, boundary_note_en, abstraction_note_en, branches_json, provenance_json, confidence, status, created_at, updated_at) VALUES ('ARC:قبل:taqabbala:an', 'قبل', 'b90cdc7da61367f79aaf032718', NULL, 'تَقَبَّلَ (عَن) + مفعول', 'عَن', 1, 1, '["46:16"]', 'القبولُ ← عن الفاعل ← كأنّه نيابةٌ عنه أو مجاوزةٌ منه', 'take up their best deeds → as they pass from them to Him', 'Once. The Lisān has the line يَقْبَلُ الأَعمال مِنْ عِبَادِهِ وَعَنْهُمْ — مِنْ and عَنْ alike. Ibn ʿĀshūr says مِنْ would be expected and reads عَنْ as ''on behalf of'', since the man also prays for his parents and children. It also mirrors the next verb, وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمْ.', NULL, NULL, '["lex:raghib_mufradat:blk_mfr_8b94d2d6edc8f942","lex:ibn_manzur_lisan_arab:blk_lsn_2855e2f2dfc64001","tafsir:ibn_ashur:46:16"]', 0.7, 'live', datetime('now'), datetime('now'));
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:8:60:alima_direct', 'ARC:علم:alima:direct', '8:60', 8, 60, 'لَا تَعۡلَمُونَهُمُ ٱللَّهُ يَعۡلَمُهُمۡ', 'you do not know them; God knows them', 'one object, a person — know who they are', 1, 'lex:raghib_mufradat:blk_mfr_b714a83893cf332d', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:29:3:alima_direct', 'ARC:علم:alima:direct', '29:3', 29, 3, 'فَلَيَعۡلَمَنَّ ٱللَّهُ ٱلَّذِينَ صَدَقُواْ وَلَيَعۡلَمَنَّ ٱلۡكَٰذِبِينَ', 'God will surely know those who are true, and He will surely know the liars', 'after the trial: the knowing sorts the true from the false', 0, 'tafsir:abu_hayyan:29:3', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:6:59:alima_direct', 'ARC:علم:alima:direct', '6:59', 6, 59, 'وَيَعۡلَمُ مَا فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ', 'and He knows what is on land and in the sea', 'the object is everything in a place — nothing left out', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:47:19:alima_anna', 'ARC:علم:alima:anna', '47:19', 47, 19, 'فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ', 'so know that there is no god but God', 'the fact itself is the object; the command is to hold it firmly', 1, 'tafsir:ibn_ashur:47:19', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:106:alima_anna', 'ARC:علم:alima:anna', '2:106', 2, 106, 'أَلَمۡ تَعۡلَمۡ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٌ', 'do you not know that God has power over everything?', 'a fact the hearer is reminded he already holds', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:6:135:alima_anna', 'ARC:علم:alima:anna', '6:135', 6, 135, 'فَسَوۡفَ تَعۡلَمُونَ مَن تَكُونُ لَهُۥ عَٰقِبَةُ ٱلدَّارِ', 'you will come to know who will have the good end', 'a question takes the place of أنَّ — the answer is left to come', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:60:10:alima_two_obj', 'ARC:علم:alima:two_obj', '60:10', 60, 10, 'فَإِنۡ عَلِمۡتُمُوهُنَّ مُؤۡمِنَٰتٖ', 'then if you find them to be believers', 'two objects: the women, and what they are judged to be', 1, 'tafsir:razi:60:10', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:96:14:alima_bi', 'ARC:علم:alima:bi', '96:14', 96, 14, 'أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ', 'does he not know that God sees?', 'بِـ: the fact should already have reached him and filled his mind', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:39:9:alima_absolute', 'ARC:علم:alima:absolute', '39:9', 39, 9, 'هَلۡ يَسۡتَوِي ٱلَّذِينَ يَعۡلَمُونَ وَٱلَّذِينَ لَا يَعۡلَمُونَ', 'are those who know and those who do not know alike?', 'no object on purpose: knowing as a quality a person has or lacks', 1, 'tafsir:ibn_ashur:39:9', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:102:3:alima_absolute', 'ARC:علم:alima:absolute', '102:3', 102, 3, 'كـَلَّا سَوۡفَ تَعۡلَمُونَ', 'no indeed — you will come to know', 'the thing to be known is held back; the gap is the threat', 0, 'tafsir:abu_hayyan:102:3', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:8:43:alim_bi', 'ARC:علم:alim:bi', '8:43', 8, 43, 'إِنَّهُۥ عَلِيمُۢ بِذَاتِ ٱلصُّدُورِ', 'He knows full well what is in the hearts', 'بِـ: knowing that goes all round the hidden thing', 1, 'lex:zabidi_taj_arus:blk_taj_523cdf4c631affa0', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:95:alim_bi', 'ARC:علم:alim:bi', '2:95', 2, 95, 'وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ', 'and God knows the wrongdoers well', 'knowing people: it carries a warning', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:29:alim_bi', 'ARC:علم:alim:bi', '2:29', 2, 29, 'وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ', 'and He knows every thing', 'the بِـ phrase put first, for stress', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:32:alim_bare', 'ARC:علم:alim:bare', '2:32', 2, 32, 'إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ', 'You are the All-Knowing, the All-Wise', 'no object: knowing as His standing name', 1, 'tafsir:razi:2:32', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:76:alim_bare', 'ARC:علم:alim:bare', '12:76', 12, 76, 'وَفَوۡقَ كُلِّ ذِي عِلۡمٍ عَلِيمٞ', 'and above every one who has knowledge is one who knows more', 'said of creatures, the same word is relative and ranked', 0, 'lex:raghib_mufradat:blk_mfr_f50f49d0798b2624', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:31:allama_two_obj', 'ARC:علم:allama:two_obj', '2:31', 2, 31, 'وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا', 'and He taught Adam the names, all of them', 'learner and lesson both named', 1, 'lex:raghib_mufradat:blk_mfr_3b6f764ab52ecae5', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:55:4:allama_two_obj', 'ARC:علم:allama:two_obj', '55:4', 55, 4, 'عَلَّمَهُ ٱلۡبَيَانَ', 'He taught him clear speech', 'a pronoun for the learner, a noun for the lesson', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:6:allama_two_obj', 'ARC:علم:allama:two_obj', '12:6', 12, 6, 'وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ', 'and He will teach you something of the meaning of events', 'مِنْ: a share of the lesson, not all of it', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:55:2:allama_one_side', 'ARC:علم:allama:one_side', '55:2', 55, 2, 'عَلَّمَ ٱلۡقُرۡءَانَ', 'He taught the Qurʾān', 'no learner named — the gift is the teaching itself', 1, 'tafsir:abu_hayyan:55:2', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:96:4:allama_one_side', 'ARC:علم:allama:one_side', '96:4', 96, 4, 'ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ', 'who taught by the pen', 'both objects left out; only the means is named', 0, 'tafsir:alusi:96:4', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:16:103:allama_one_side', 'ARC:علم:allama:one_side', '16:103', 16, 103, 'إِنَّمَا يُعَلِّمُهُۥ بَشَرٞ', 'it is only a man who teaches him', 'the lesson left out; the charge is about the teacher', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:49:16:allama_bi', 'ARC:علم:allama:bi', '49:16', 49, 16, 'أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ', 'would you inform God of your religion?', 'بِـ turns teaching into telling — and no one can tell God anything', 1, 'tafsir:alusi:49:16', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:39:53:ghafara_direct', 'ARC:غفر:ghafara:direct', '39:53', 39, 53, 'إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًا', 'God forgives all sins', 'the sins themselves are the object — all of them', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:135:ghafara_direct', 'ARC:غفر:ghafara:direct', '3:135', 3, 135, 'وَمَن يَغۡفِرُ ٱلذُّنُوبَ إِلَّا ٱللَّهُ', 'and who forgives sins but God?', 'no person named: only the sins, and only One who covers them', 0, 'lex:raghib_mufradat:blk_mfr_875c2509db26c773', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:129:ghafara_li', 'ARC:غفر:ghafara:li', '3:129', 3, 129, 'يَغۡفِرُ لِمَن يَشَآءُ', 'He forgives whom He wills', 'only the person is named; the cover is for him', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:16:ghafara_li', 'ARC:غفر:ghafara:li', '3:16', 3, 16, 'فَٱغۡفِرۡ لَنَا ذُنُوبَنَا', 'so forgive us our sins', 'both: the people by لـ, the sins as object', 0, 'lex:lane_lexicon:blk_lane_8d21a7cc45be169d', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:14:10:ghafara_li', 'ARC:غفر:ghafara:li', '14:10', 14, 10, 'لِيَغۡفِرَ لَكُم مِّن ذُنُوبِكُمۡ', 'to forgive you some of your sins', 'مِنْ takes a part of the sins', 0, 'tafsir:zamakhshari:14:10', 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:42:37:ghafara_absolute', 'ARC:غفر:ghafara:absolute', '42:37', 42, 37, 'وَإِذَا مَا غَضِبُواْ هُمۡ يَغۡفِرُونَ', 'and when they are angry, they forgive', 'no one named: forgiving as part of who they are', 1, 'tafsir:abu_hayyan:42:37', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:64:14:ghafara_absolute', 'ARC:غفر:ghafara:absolute', '64:14', 64, 14, 'وَإِن تَعۡفُواْ وَتَصۡفَحُواْ وَتَغۡفِرُواْ', 'and if you pardon, overlook and forgive', 'three verbs, no object: a way of living with family', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:71:10:istaghfara_direct', 'ARC:غفر:istaghfara:direct', '71:10', 71, 10, 'ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا', 'ask your Lord to forgive you — He is ever forgiving', 'the one asked is the object', 1, 'lex:raghib_mufradat:blk_mfr_6e5128ad5f5d3cf3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:110:3:istaghfara_direct', 'ARC:غفر:istaghfara:direct', '110:3', 110, 3, 'وَٱسۡتَغۡفِرۡهُ', 'and ask Him for forgiveness', 'a pronoun for God as object', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:55:istaghfara_li_dhanb', 'ARC:غفر:istaghfara:li_dhanb', '40:55', 40, 55, 'وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ', 'and ask forgiveness for your sin', 'لـ names the fault, not a person', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:12:29:istaghfara_li_dhanb', 'ARC:غفر:istaghfara:li_dhanb', '12:29', 12, 29, 'وَٱسۡتَغۡفِرِي لِذَنۢبِكِ', 'and ask forgiveness for your sin', 'the same frame, said to the wife who wronged Yūsuf', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:47:19:istaghfara_li_person', 'ARC:غفر:istaghfara:li_person', '47:19', 47, 19, 'وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ', 'ask forgiveness for your sin, and for the believing men and women', 'one verb, two lāms: your own fault, then others', 1, 'tafsir:ibn_ashur:47:19', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:80:istaghfara_li_person', 'ARC:غفر:istaghfara:li_person', '9:80', 9, 80, 'ٱسۡتَغۡفِرۡ لَهُمۡ أَوۡ لَا تَسۡتَغۡفِرۡ لَهُمۡ', 'ask forgiveness for them or do not', 'pleading for others — and the plea refused', 0, 'lex:raghib_mufradat:blk_mfr_75878a5ada007f51', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:19:47:istaghfara_li_person', 'ARC:غفر:istaghfara:li_person', '19:47', 19, 47, 'سَأَسۡتَغۡفِرُ لَكَ رَبِّيٓ', 'I will ask my Lord to forgive you', 'Ibrāhīm pleads for his father; God is also named', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:51:18:istaghfara_absolute', 'ARC:غفر:istaghfara:absolute', '51:18', 51, 18, 'وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ', 'and before dawn they ask forgiveness', 'a habit at a set time; nothing else is named', 1, 'tafsir:abu_hayyan:51:18', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:8:33:istaghfara_absolute', 'ARC:غفر:istaghfara:absolute', '8:33', 8, 33, 'وَهُمۡ يَسۡتَغۡفِرُونَ', 'while they ask forgiveness', 'asking as a state that holds punishment back', 0, 'tafsir:ibn_ashur:8:33', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:3:ghafir_idafa', 'ARC:غفر:ghafir:idafa', '40:3', 40, 3, 'غَافِرِ ٱلذَّنۢبِ', 'Forgiver of sin', 'named by what He covers — a mark of Him, not a single event', 1, 'tafsir:alusi:40:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:11:dhanb_bi', 'ARC:ذنب:dhanb:bi', '3:11', 3, 11, 'فَأَخَذَهُمُ ٱللَّهُ بِذُنُوبِهِمۡ', 'so God seized them for their sins', 'بِـ of cause: the seizing comes behind the sins', 1, 'tafsir:abu_hayyan:3:11', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:91:14:dhanb_bi', 'ARC:ذنب:dhanb:bi', '91:14', 91, 14, 'فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ', 'so their Lord crushed them for their sin', 'one sin named as the cause of the ruin', 0, 'tafsir:zamakhshari:91:14', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:81:9:dhanb_bi', 'ARC:ذنب:dhanb:bi', '81:9', 81, 9, 'بِأَيِّ ذَنۢبٖ قُتِلَتۡ', 'for what sin she was killed', 'the question asks for a cause, and there was none', 0, NULL, 3);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:26:14:dhanb_lahum_ala', 'ARC:ذنب:dhanb:lahum_ala', '26:14', 26, 14, 'وَلَهُمۡ عَلَيَّ ذَنۢبٞ', 'and they have a charge against me', 'لـ the claimants, عَلَى the one who owes: the sin has become a debt', 1, 'tafsir:ibn_ashur:26:14', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:85:qabila_min', 'ARC:قبل:qabila:min', '3:85', 3, 85, 'فَلَن يُقۡبَلَ مِنۡهُ', 'it will never be accepted from him', 'مِنْ: the giver is named, and his offer turned back', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:123:qabila_min', 'ARC:قبل:qabila:min', '2:123', 2, 123, 'وَلَا يُقۡبَلُ مِنۡهَا عَدۡلٞ', 'no ransom will be accepted from it', 'the thing offered as object, the giver by مِنْ', 0, 'lex:raghib_mufradat:blk_mfr_a98aa671ca3e65a5', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:9:104:qabila_an', 'ARC:قبل:qabila:an', '9:104', 9, 104, 'يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ', 'He accepts repentance from His servants', 'عَنْ: the repentance is taken, and the sin passes away from them', 1, 'tafsir:alusi:9:104', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:42:25:qabila_an', 'ARC:قبل:qabila:an', '42:25', 42, 25, 'وَهُوَ ٱلَّذِي يَقۡبَلُ ٱلتَّوۡبَةَ عَنۡ عِبَادِهِۦ', 'He is the One who accepts repentance from His servants', 'followed at once by وَيَعْفُوا عَنِ ٱلسَّيِّـَٔاتِ — the pardon spelled out', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:90:qabila_direct', 'ARC:قبل:qabila:direct', '3:90', 3, 90, 'لَّن تُقۡبَلَ تَوۡبَتُهُمۡ', 'their repentance will not be accepted', 'the owner sits inside the object (their), not after a particle', 1, NULL, 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:24:4:qabila_direct', 'ARC:قبل:qabila:direct', '24:4', 24, 4, 'وَلَا تَقۡبَلُواْ لَهُمۡ شَهَٰدَةً أَبَدٗا', 'and never accept any testimony from them', 'a legal sense: their word no longer counts', 0, 'tafsir:alusi:24:4', 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:40:3:qabil_idafa', 'ARC:قبل:qabil:idafa', '40:3', 40, 3, 'وَقَابِلِ ٱلتَّوۡبِ', 'Accepter of repentance', 'named by what He receives — the turning back of His servants', 1, 'tafsir:ibn_ashur:40:3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:5:27:taqabbala_min', 'ARC:قبل:taqabbala:min', '5:27', 5, 27, 'إِنَّمَا يَتَقَبَّلُ ٱللَّهُ مِنَ ٱلۡمُتَّقِينَ', 'God accepts only from those who are mindful of Him', 'مِنْ: whose offering it is decides whether it is taken', 1, 'lex:raghib_mufradat:blk_mfr_df144a7c47479038', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:2:127:taqabbala_min', 'ARC:قبل:taqabbala:min', '2:127', 2, 127, 'رَبَّنَا تَقَبَّلۡ مِنَّآ', 'our Lord, accept from us', 'the offering (the House they built) is left unsaid; only the givers are named', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:3:37:taqabbala_direct', 'ARC:قبل:taqabbala:direct', '3:37', 3, 37, 'فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ', 'so her Lord accepted her with a fine acceptance', 'the vowed child is the object: received, and taken into care', 1, 'lex:raghib_mufradat:blk_mfr_548782de70b4e0d3', 1);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:14:40:taqabbala_direct', 'ARC:قبل:taqabbala:direct', '14:40', 14, 40, 'رَبَّنَا وَتَقَبَّلۡ دُعَآءِ', 'our Lord, accept my prayer', 'the prayer itself is the thing offered up', 0, NULL, 2);
INSERT OR REPLACE INTO ar_ling_lemma_arc_example (id, arc_id, qr_ref, surah, ayah, text_ar, fluent_en, note_en, is_primary, source_ref, seq) VALUES ('AEX:46:16:taqabbala_an', 'ARC:قبل:taqabbala:an', '46:16', 46, 16, 'أُوْلَٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ', 'those are the ones from whom We accept the best of what they did', 'عَنْ, matched by عَن سَيِّـَٔاتِهِمْ right after', 1, 'tafsir:ibn_ashur:46:16', 1);
-- The government row عَلِمَ … مِنْ, corrected: the dictionaries never pair عَلِمَ with مِنْ, and at 2:143 / 34:21 the مِنْ is
-- مِمَّنْ's — but at 2:220 «يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ» Abū Ḥayyān ties مِنْ to the verb ("tell apart") and Ibn ʿĀshūr calls it
-- the مِنْ of separation. Kept as a branch of the direct arc (ARC:علم:alima:*), not an arc of its own.
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.note_en',
  'The dictionaries never pair عَلِمَ with مِنْ; at 2:143 and 34:21 the مِنْ is مِمَّنْ''s ("from among"). At 2:220 «يَعْلَمُ الْمُفْسِدَ مِنَ الْمُصْلِحِ» the tafsīr ties مِنْ to the verb — "knows apart": Abū Ḥayyān; Ibn ʿĀshūr, the مِنْ of separation.')
 WHERE id = 'TDY:QR:SP:SV:علم:I:11';
